                        EmailAddresses = new List<string> { "sonjalk@unops.org", "yngvilf@unops.org", "eo.cph@unops.org", "freyavg@unops.org", "kirstined@unops.org", "plg.lo@unops.org", "markuso@unops.org", "djenebas@unops.org", "thomasl@unops.org", "svene@unops.org", "karls@unops.org", "rahulm@unops.org", "arnauds@unops.org", "hilaryb@unops.org", "orenng@unops.org", "carolinapo@unops.org" },
