                ),
                new (
                    "00TQx00000PjxiOMAR",
                    new UNOPSInteraction
                    {
                        Name = "Email: UNOPS Support to Comunità Sant'Egidio",
                        Type = InteractionType.Email,
                        Date = DateTime.Parse("2025-05-28").ToUniversalTime(),
                        Subject = "Email: UNOPS Support to Comunità Sant'Egidio",
                        Description = "To: roberto.mengoni@esteri.it; giovanni.guidotti@dreamsantegidio.net; isabelle.ziegler@dreamsantegidio.net; rainerf@unops.org; elenage@unops.org\nCC: \nBCC: \nAttachment: --none--\n\nSubject: UNOPS Support to Comunità Sant'Egidio\nBody:\nDear Roberto and Dr Guidotti:\nI hope my message finds you well.We received the list of materials needed for Comunità Sant'Egidio operations.In order to deepen on certain particularities about the list, and the locations for its delivery, we would like to have a meeting with you at your earliest convenience.Rainer Fraunfeld, Multi Country Office Director of South & Eastern Africa will be joining, and will be the responsible operation officer for this effort. That is, the planning and design right now, and the implementation later hopefully.\nThank you for your attention and please let us know when we could have the meeting.\nCheers,\nMartín Arévalo de León | Representative and Head | Partnerships & Liaisons Group | Rome Liaison Office | Rome, Italy | Cel +39 344 778 3550 | www.unops.org Follow us on social media and subscribe to our newsletter. | www.unops.org",
                        Location = null,
                        GmailThreadId = null,
                        GmailMessageId = "00TQx00000PjxiOMAR",
                        EmailAddresses = new List<string> { "isabelle.ziegler@dreamsantegidio.net", "rainerf@unops.org", "elenage@unops.org", "giovanni.guidotti@dreamsantegidio.net", "roberto.mengoni@esteri.it" },
                        Status = (EntityStatus)1,
                        CreatedBy = paoUserEmailMapping.ContainsKey("martina@unops.org".ToLower()) ? paoUserEmailMapping["martina@unops.org".ToLower()] : 0,
                        CreatedDate = DateTime.UtcNow,
                        LastModifiedBy = 0,
                        LastModifiedDate = DateTime.UtcNow,
                        IsDeleted = false,
                        DeletedBy = 0
                    },
                    new List<string> { "003Qx00000KJXCxIAP" },
