                new (
                    "00TQx00000OugI5MAJ",
                    new UNOPSInteraction
                    {
                        Name = "Email: WFP - UNOPS collaboration",
                        Type = InteractionType.Email,
                        Date = DateTime.Parse("2025-05-08").ToUniversalTime(),
                        Subject = "Email: WFP - UNOPS collaboration",
                        Description = "To: sara.adam@wfp.org\nCC: betty.ka@wfp.org; rainatou.baillet@wfp.org\nBCC: \nAttachment: --none--\n\nSubject: WFP - UNOPS collaboration\nBody:\nDear Sara:\nIt's a pleasure making your acquaintance, virtually at least.Since our EDs met in late November last year, we have been discussing with Betty Ka on the possibility of setting a strategic collaboration framework between our agencies, and avoid overlapping, double efforts and competition.We have been discussing with Rainatou Baillet and our Procurement Group to determine complementarities and strong points of each agency, and infrastructure logistics has sprung as an aspect to be covered.I would like to connect with you, as this would not be the first time such talks have taken place.Please let me know when we could talk and I would be happy to visit you.\nCheers,\nMartín Arévalo de León | Representative and Head | Partnerships & Liaisons Group | Rome Liaison Office | Rome, Italy | Cel +39 344 778 3550 | www.unops.org Follow us on social media and subscribe to our newsletter. | www.unops.org",
                        Location = null,
                        GmailThreadId = null,
                        GmailMessageId = "00TQx00000OugI5MAJ",
                        EmailAddresses = new List<string> { "rainatou.baillet@wfp.org", "sara.adam@wfp.org", "betty.ka@wfp.org" },
                        Status = (EntityStatus)1,
