                ),
                new (
                    "00TQx00000NRDdZMAX",
                    new UNOPSInteraction
                    {
                        Name = "Email: Opfølgning på info-møde om Gaza og Syrien",
                        Type = InteractionType.Email,
                        Date = DateTime.Parse("2025-04-01").ToUniversalTime(),
                        Subject = "Email: Opfølgning på info-møde om Gaza og Syrien",
                        Description = "To: tavest@um.dk; adwmoh@um.dk\nCC: marijab@unops.org; naimoh@unops.org\nBCC: \nAttachment: --none--\n\nSubject: Opfølgning på info-møde om Gaza og Syrien\nBody:\nKære Tanja og Adwan, \nSom opfølgning på vores samtale med Bana om situationen i Gaza og Syrien for et par uger siden, er vedlagt til jeres orientering oversigt over UNOPS' operationer i Syrien og Gaza. \nDer er som bekendt et stort finansieringsbehov i Gaza - herunder særligt hastende til levering af brændstof til at holde gang i nødgeneratorer. For Syren ser vi især behov for genopbygning af sundheds- og uddannelsesinfrastruktur samt indkøb af medicinsk udstyr. \nJeg hører meget gerne fra jer, såfremt der fra dansk side skulle være interesse for en videre dialog om evt. dansk hjælp til indsatsen. \nVi står til jeres rådighed for evt. opfølgning - og håber at høre fra jer. \nPå forhånd mange tak. \nMvhAsbjørn \n-- \n\nAsbjørn Brink| Head of Northern Europe Liaison Office | Partnerships and Liaison Group | HQ | Copenhagen, Denmark | Tel: +45 40 80 36 54 | Follow us on social media and subscribe to our newsletter. | www.unops.org",
                        Location = null,
                        GmailThreadId = null,
                        GmailMessageId = "00TQx00000NRDdZMAX",
                        EmailAddresses = new List<string> { "tavest@um.dk", "naimoh@unops.org", "marijab@unops.org", "adwmoh@um.dk" },
                        Status = (EntityStatus)1,
                        CreatedBy = paoUserEmailMapping.ContainsKey("asbjornb@unops.org".ToLower()) ? paoUserEmailMapping["asbjornb@unops.org".ToLower()] : 0,
                        CreatedDate = DateTime.UtcNow,
                        LastModifiedBy = 0,
