                    new List<string> { "B0047" }
                ),
                new (
                    "00TQx00000NF9h3MAD",
                    new UNOPSInteraction
                    {
                        Name = "Email: Request for meeting between The Rt Hon. Ed Miliband and UN Under-Secretary-General and UNOPS Executive Director, Jorge Moreira da Silva",
                        Type = InteractionType.Email,
                        Date = DateTime.Parse("2025-03-27").ToUniversalTime(),
                        Subject = "Email: Request for meeting between The Rt Hon. Ed Miliband and UN Under-Secretary-General and UNOPS Executive Director, Jorge Moreira da Silva",
                        Description = "To: simon.hampton-ball@energysecurity.gov.uk\nCC: kerriet@unops.org; asbjornb@unops.org\nBCC: \nAttachment: --none--\n\nSubject: Request for meeting between The Rt Hon. Ed Miliband and UN Under-Secretary-General and UNOPS Executive Director, Jorge Moreira da Silva\nBody:\nDear Simon,\nI hope this email finds you well.\nI will be travelling to London on 7 April, and would greatly appreciate an opportunity to meet with The Rt. Hon. Ed Miliband, Secretary of State for Energy Security and Net Zero.\nMay I please ask for your kind support in brining the attached letter of request to the The Rt Hon. Ed Miliband's attention.\nIf agreed, my assistant Kerrie (copied), would be happy to work with you to schedule the meeting.\nMany thanks in advance.\n-- \nSincerely,Jorge Moreira da SilvaUN Under-Secretary-General and UNOPS Executive Director\nSent on behalf of USG Moreira da Silva\nUNOPS Executive Office | Copenhagen, Denmark | Follow us on social media and subscribe to our newsletter. | www.unops.org",
                        Location = null,
                        GmailThreadId = null,
