                        EmailAddresses = new List<string> { "simonp@unops.org", "sadias@unops.org", "simonettas@unops.org", "seynaboud@unops.org", "fatoufn@unops.org", "leyres@unops.org", "amyn@unops.org", "fabriziof@unops.org", "sanjaym@unops.org", "claudiar@unops.org", "workneshg@unops.org", "lesliemh@unops.org", "plg.personnel@unops.org", "sophiedj@unops.org", "eloiselm@unops.org", "kelleys@unops.org", "dabagaid@unops.org", "elizabethdu@unops.org", "sirpaj@unops.org", "sonjalk@unops.org", "lwandak@unops.org", "petronellah@unops.org", "claragh@unops.org", "svene@unops.org", "dalilag@unops.org", "joeenas@unops.org", "lydiaat@unops.org", "akiram@unops.org", "nivesc@unops.org", "antonk@unops.org", "abdoulazizs@unops.org", "sofiateresama@unops.org", "alaan@unops.org", "muhammada@unops.org", "elenage@unops.org", "reemas@unops.org", "emiliep@unops.org", "kirstined@unops.org", "basazinewt@unops.org", "juliasc@unops.org", "marijab@unops.org", "alicen@unops.org", "francescap@unops.org", "jakobt@unops.org", "tanjac@unops.org", "fumiea@unops.org", "solv@unops.org", "eleneag@unops.org", "nicolej@unops.org", "timl@unops.org", "vineshw@unops.org", "freyavg@unops.org", "itaim@unops.org", "robertgodin@unops.org", "tokumitsuk@unops.org", "banak@unops.org", "sonjav@unops.org", "partnerships.focal.points@unops.org", "alistairs@unops.org", "christinebo@unops.org" },
