                ),
                new (
                    "00TQx00000INb4oMAD",
                    new UNOPSInteraction
                    {
                        Name = "Email: Anmodning om møde: UNOPS og Norge i Kenya",
                        Type = InteractionType.Email,
                        Date = DateTime.Parse("2024-11-21").ToUniversalTime(),
                        Subject = "Email: Anmodning om møde: UNOPS og Norge i Kenya",
                        Description = "To: Magnus.Baumann.Lorentzen@mfa.no\nCC: naimoh@unops.org; elenage@unops.org; fumiea@unops.org\nBCC: \nAttachment: --none--\n\nSubject: Anmodning om møde: UNOPS og Norge i Kenya\nBody:\nKære Magnus\nJeg rækker ud til dig som opfølgning på dialog med dine kolleger i Oslo, da jeg snart skal på mission til Østafrika med henblik på at se nogle af de projekter, som vi i UNOPS gennemfører på vegne af partnere. I den forbindelse ville jeg også meget gerne mødes med repræsentanter for nordiske partnere med henblik på at drøfte evt. samarbejdsmuligheder - især som opfølgning på Norges nye Afrikastrategi. \nJeg vil være i Nairobi i perioden 2-5 december og ville meget gerne mødes med dig og evt. dine relevante kolleger på et tidspunkt, som kunne passe dig. \nFormålet med mødet vil bl.a. være opfølgning på mødet mellem vores regionale afrikadirektørs (Dalila) møde med den norske ambassadør for et par måneder siden, hvor vi kunne se på evt. synergier mellem Norges Afrikastrategi, prioriteter, og UNOPS' arbejde på det afrikanske kontinent. \nVi har bl.a. bemærket, at den nye norske afrikastrategi understreget behovet for en stærk forpligtelse til at understøtte bæredygtig udvikling, uddannelse og sundhed, menneskerettigheder og sikkerhed i de afrikanske samfund. I UNOPS gennemfører vi pt. adskillige projekter i Afrika som er på linje med norske prioriteter, såsom opbygning af bæredygtig energiinfrastruktur, vandforsyning, kvinderettigheder, opførelse af skoler mv. \nJeg ville derfor sætte stor pris på, om du og evt. dine relevante kolleger havde mulighed for at mødes på et tidspunkt, som passer dig i perioden 2-5 december. Lad mig meget gerne vide hvornår det kunne passe dig. \nPå forhånd mange tak! \nPS - til din orientering har jeg også forsøgt at sende en mail adresseret til din kollega Camilla Ravnsborg Aschjem - dog uden held, da jeg ikke har hendes direkte e-mail (vedlagt korrespondance). \nJeg ser meget frem til at høre fra dig. \nMvhAsbjørn\n\nAsbjørn Brink | Head of Northern Europe Liaison Office | Partnerships and Liaison Group | UNOPS HQ | Copenhagen, Denmark | Mob: +45 40 80 36 54 | www.unops.org Keep up-to-date with UNOPS. Follow us on Facebook, LinkedIn, Twitter, Instagram, YouTube Subscribe to our external newsletter in English, French or Spanish.",
                        Location = null,
                        GmailThreadId = null,
                        GmailMessageId = "00TQx00000INb4oMAD",
                        EmailAddresses = new List<string> { "naimoh@unops.org", "magnus.baumann.lorentzen@mfa.no", "fumiea@unops.org", "elenage@unops.org" },
                        Status = (EntityStatus)1,
