                        GmailThreadId = null,
                        GmailMessageId = "00TQx00000GvW5DMAV",
                        EmailAddresses = new List<string> { "elenage@unops.org", "amyn@unops.org", "lalpou@um.dk", "dalilag@unops.org", "sarahdg@unops.org", "naimoh@unops.org", "ketkar@um.dk" },
