                        GmailMessageId = "00TQx00000M2poGMAR",
                        EmailAddresses = new List<string> { "sindyum@unops.org", "cingles@colegioquimicohn.com", "samuelaguilar@arsa.gob.hn", "linasabogal@unops.org", "gladysmorel@arsa.gob.hn", "lauragi@unops.org", "astridnolasco@arsa.gob.hn", "mariaru@unops.org", "karenpadgett2012@gmail.com", "mariajoseulmisesal@gmail.com", "linamosquera@unops.org", "mariasoto@salud.gob.hn", "mariacasco@arsa.gob.hn", "alexdiaz@arsa.gob.hn", "mrodriguez@colegioquimicohn.com", "sevillamarcio247@gmail.com", "mariosantos@arsa.gob.hn", "hponce@colegioquimicohn.com", "carolinaca@unops.org" },
